import{_ as e,o as i,c as s,a2 as a}from"./chunks/framework.CBxkvBm_.js";const p=JSON.parse('{"title":"URDF & Xacro Robot Kinematics & Featherstone Dynamics","description":"Native compiler support for ROS URDF (.urdf) and Xacro (.xacro) robot models, spatial kinematics, Featherstone recursive dynamics (ABA, RNEA), and 3D CAD/Modelica projections in ModelScript.","frontmatter":{"title":"URDF & Xacro Robot Kinematics & Featherstone Dynamics","description":"Native compiler support for ROS URDF (.urdf) and Xacro (.xacro) robot models, spatial kinematics, Featherstone recursive dynamics (ABA, RNEA), and 3D CAD/Modelica projections in ModelScript."},"headers":[],"relativePath":"languages/urdf.md","filePath":"languages/urdf.md"}'),o={name:"languages/urdf.md"};function l(n,t,r,d,c,g){return i(),s("div",null,[...t[0]||(t[0]=[a(`<h1 id="urdf-xacro-robot-kinematics" tabindex="-1">URDF &amp; Xacro Robot Kinematics <a class="header-anchor" href="#urdf-xacro-robot-kinematics" aria-label="Permalink to &quot;URDF &amp; Xacro Robot Kinematics&quot;">​</a></h1><p>ModelScript provides first-class support for <strong>URDF</strong> (<code>.urdf</code>) and <strong>Xacro</strong> (<code>.xacro</code>), the robotics industry and ROS (Robot Operating System) standard for describing kinematic trees, inertial properties, visual geometry, and joint limits of robotic manipulators, humanoids, and autonomous vehicles.</p><hr><h2 id="capabilities-supported-formats" tabindex="-1">Capabilities &amp; Supported Formats <a class="header-anchor" href="#capabilities-supported-formats" aria-label="Permalink to &quot;Capabilities &amp; Supported Formats&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Format</th><th style="text-align:left;">Extension</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Unified Robot Description Format</strong></td><td style="text-align:left;"><code>.urdf</code>, <code>.xml</code></td><td style="text-align:left;">XML schema defining kinematic links, joints (revolute, continuous, prismatic, fixed, floating, planar), inertial parameters, collision bounds, and visual meshes.</td></tr><tr><td style="text-align:left;"><strong>Xacro Macro Template</strong></td><td style="text-align:left;"><code>.xacro</code></td><td style="text-align:left;">Parametric XML preprocessor adding variables (<code>&lt;xacro:property&gt;</code>), mathematical expressions, and reusable macros (<code>&lt;xacro:macro&gt;</code>).</td></tr></tbody></table><h3 id="key-architectural-features" tabindex="-1">Key Architectural Features <a class="header-anchor" href="#key-architectural-features" aria-label="Permalink to &quot;Key Architectural Features&quot;">​</a></h3><ul><li><strong>Xacro Expansion &amp; Parser:</strong><ul><li>Robust XML reader with automatic in-memory macro expansion (<code>&lt;xacro:macro&gt;</code>) and mathematical expression evaluation before parsing.</li><li>Generates strongly typed robot AST representation via <code>parseUrdf()</code>.</li></ul></li><li><strong>Topological Kinematic Tree &amp; Featherstone Algorithms:</strong><ul><li>Traverses joint-link connectivity starting from the root base link.</li><li>Implements <strong>Recursive Newton-Euler Algorithm (RNEA)</strong> for inverse dynamics: calculates required joint torques $\\boldsymbol{\\tau}$ given joint positions $\\mathbf{q}$, velocities $\\dot{\\mathbf{q}}$, and accelerations $\\ddot{\\mathbf{q}}$.</li><li>Implements <strong>Articulated-Body Algorithm (ABA)</strong> for forward dynamics: evaluates forward acceleration $\\ddot{\\mathbf{q}} = \\mathbf{M}(\\mathbf{q})^{-1} (\\boldsymbol{\\tau} - \\mathbf{C}(\\mathbf{q}, \\dot{\\mathbf{q}}) - \\mathbf{g}(\\mathbf{q}))$ in $O(N)$ operations.</li></ul></li><li><strong>Robotics Linters (<code>M7501</code>–<code>M7510</code>):</strong><ul><li>Detects dangling parent/child link references, disconnected kinematic sub-trees, inverted joint limits (<code>lower &gt; upper</code>), zero joint axis vectors, missing inertia tags, and non-physical inertia tensors.</li></ul></li><li><strong>Multi-Target Projections:</strong><ul><li><strong>Modelica MultiBody:</strong> Synthesizes <code>Modelica.Mechanics.MultiBody</code> robotic arms with joint friction and actuator controllers.</li><li><strong>MSC Adams:</strong> Exports Adams <code>.adm</code> solver datasets.</li><li><strong>SIMPACK:</strong> Generates SIMPACK <code>.spck</code> mechanisms.</li><li><strong>3D CAD:</strong> Projects robot geometry into CSG primitives and STEP visual meshes.</li></ul></li></ul><hr><h2 id="command-line-interface-msx-urdf" tabindex="-1">Command Line Interface (<code>msx urdf</code>) <a class="header-anchor" href="#command-line-interface-msx-urdf" aria-label="Permalink to &quot;Command Line Interface (\`msx urdf\`)&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">msx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> urdf</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">actio</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [files...] [options]</span></span></code></pre></div><table tabindex="0"><thead><tr><th style="text-align:left;">Action</th><th style="text-align:left;">Description</th><th style="text-align:left;">Key Options</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><code>inspect</code></strong></td><td style="text-align:left;">Dumps robot name, root link, joint tree, mass budget, and degrees of freedom.</td><td style="text-align:left;">—</td></tr><tr><td style="text-align:left;"><strong><code>lint</code></strong></td><td style="text-align:left;">Runs kinematic tree validation, joint limit checks, and inertia verification.</td><td style="text-align:left;">—</td></tr><tr><td style="text-align:left;"><strong><code>dynamics</code></strong></td><td style="text-align:left;">Evaluates forward (ABA) or inverse (RNEA) dynamics at test joint coordinates.</td><td style="text-align:left;"><code>--q=&lt;csv&gt;</code>, <code>--qd=&lt;csv&gt;</code>, <code>--qdd=&lt;csv&gt;</code>, <code>--tau=&lt;csv&gt;</code></td></tr><tr><td style="text-align:left;"><strong><code>to-modelica</code></strong></td><td style="text-align:left;">Generates standard <code>Modelica.Mechanics.MultiBody</code> robot system.</td><td style="text-align:left;"><code>--out=&lt;file.mo&gt;</code></td></tr><tr><td style="text-align:left;"><strong><code>to-adams</code></strong></td><td style="text-align:left;">Projects robot mechanism into MSC Adams <code>.adm</code> solver dataset.</td><td style="text-align:left;"><code>--out=&lt;file.adm&gt;</code></td></tr><tr><td style="text-align:left;"><strong><code>to-simpack</code></strong></td><td style="text-align:left;">Projects robot mechanism into SIMPACK XML <code>.spck</code> model.</td><td style="text-align:left;"><code>--out=&lt;file.spck&gt;</code></td></tr><tr><td style="text-align:left;"><strong><code>to-dae</code></strong></td><td style="text-align:left;">Lowers kinematic state equations directly into <code>DAEBuilder</code> arena.</td><td style="text-align:left;">—</td></tr></tbody></table><h3 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Inspect robot kinematic hierarchy and total mass</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">msx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> urdf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> inspect</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> KukaIiwa14.urdf</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Check for inverted joint limits or dangling parent links</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">msx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> urdf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lint</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> MobileManipulator.urdf</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Convert robot description into standard Modelica 3.x</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">msx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> urdf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> to-modelica</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PandaArm.urdf</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --out=PandaArm.mo</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Export to MSC Adams for vehicle-mounted robot simulation</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">msx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> urdf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> to-adams</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> RoverArm.urdf</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --out=RoverArm.adm</span></span></code></pre></div><hr><h2 id="robotics-linters-diagnostic-rules" tabindex="-1">Robotics Linters &amp; Diagnostic Rules <a class="header-anchor" href="#robotics-linters-diagnostic-rules" aria-label="Permalink to &quot;Robotics Linters &amp; Diagnostic Rules&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Code</th><th style="text-align:left;">Identifier</th><th style="text-align:left;">Severity</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><code>M7501</code></strong></td><td style="text-align:left;"><code>dangling-parent-link</code></td><td style="text-align:left;">Error</td><td style="text-align:left;">Joint references a parent link name that does not exist in the robot description.</td></tr><tr><td style="text-align:left;"><strong><code>M7502</code></strong></td><td style="text-align:left;"><code>dangling-child-link</code></td><td style="text-align:left;">Error</td><td style="text-align:left;">Joint references a child link name that does not exist in the robot description.</td></tr><tr><td style="text-align:left;"><strong><code>M7503</code></strong></td><td style="text-align:left;"><code>disconnected-kinematic-tree</code></td><td style="text-align:left;">Error</td><td style="text-align:left;">One or more links cannot be reached via kinematic joints from the root link.</td></tr><tr><td style="text-align:left;"><strong><code>M7504</code></strong></td><td style="text-align:left;"><code>cyclic-kinematic-chain</code></td><td style="text-align:left;">Error</td><td style="text-align:left;">Joint hierarchy contains a cycle; URDF requires a strictly acyclic tree topology.</td></tr><tr><td style="text-align:left;"><strong><code>M7505</code></strong></td><td style="text-align:left;"><code>missing-inertial-tag</code></td><td style="text-align:left;">Warning</td><td style="text-align:left;">Non-fixed moving link omits <code>&lt;inertial&gt;</code> mass and inertia tensor definition.</td></tr><tr><td style="text-align:left;"><strong><code>M7506</code></strong></td><td style="text-align:left;"><code>non-physical-inertia</code></td><td style="text-align:left;">Error</td><td style="text-align:left;">Link inertia tensor violates positive-definiteness or triangle inequality.</td></tr><tr><td style="text-align:left;"><strong><code>M7507</code></strong></td><td style="text-align:left;"><code>zero-joint-axis</code></td><td style="text-align:left;">Error</td><td style="text-align:left;">Revolute or prismatic joint specifies a zero axis vector (<code>xyz=&quot;0 0 0&quot;</code>).</td></tr><tr><td style="text-align:left;"><strong><code>M7508</code></strong></td><td style="text-align:left;"><code>inverted-joint-limits</code></td><td style="text-align:left;">Error</td><td style="text-align:left;">Joint lower limit exceeds the upper limit (<code>limit lower &gt; upper</code>).</td></tr><tr><td style="text-align:left;"><strong><code>M7509</code></strong></td><td style="text-align:left;"><code>zero-effort-limit</code></td><td style="text-align:left;">Warning</td><td style="text-align:left;">Active non-fixed joint specifies maximum effort limit of zero.</td></tr><tr><td style="text-align:left;"><strong><code>M7510</code></strong></td><td style="text-align:left;"><code>missing-visual-or-collision</code></td><td style="text-align:left;">Info</td><td style="text-align:left;">Link does not declare any visual or collision geometry.</td></tr></tbody></table>`,16)])])}const m=e(o,[["render",l]]);export{p as __pageData,m as default};
